// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function testFuzz_property(uint256 ts) public {
        // keep timestamp in a wide, valid domain; the fuzzer searches it so that
        // sometimes the pseudo-random outcome is 1 (no payout) and sometimes 0
        ts = bound(ts, 1, type(uint256).max / 2);
        vm.warp(ts);

        // an EOA player (transfers to EOAs always succeed)
        address actor = address(uint160(bound(uint256(uint160(address(this))) + ts, 1, type(uint160).max)));
        vm.deal(actor, 10);

        vm.prank(actor);
        try c.play{value: 10}() {
            // play succeeded
        } catch {
            // play reverted; state unchanged, invariant must still hold
        }

        // General rule: the contract's native balance always equals its pot.
        // Reference: each play banks 10 wei into balance and pot alike; a win
        // pays out pot (and fee) and zeroes pot, keeping them equal.
        // Mutant: banks 10 wei into balance but only 1 into pot, so after a
        // play that does not pay out (or any play), balance != pot.
        assertTrue(address(c).balance == c.pot());
    }
}
